package com.nth.desktop3d;

import android.app.Instrumentation;
import android.graphics.*;
import android.graphics.drawable.ColorDrawable;
import android.os.*;
import android.view.*;
import android.widget.*;
import java.util.*;
import org.json.*;

/** Actual Android drags from the drawer, edge dwell, cancellation, overflow and app resizing. */
public final class CardsPlacement093Smoke extends Trial093Support {
    public CardsPlacement093Smoke(Instrumentation test,MainActivity activity,String output){super(test,activity,output);}
    public void run()throws Exception {snapshot();try{fixture();drawerAndEdges();appTiles();overflow();}finally{main(()->((DrawerDragController)field(activity,"drawerDrags")).cancel());restore();}}
    private void fixture(){main(()->{try{call(activity,"closePanel");for(List<LauncherStore.Item> page:store.pages)page.clear();store.page=0;store.setHomePage(0);for(int p=0;p<store.pageCount();p++)store.preferences.edit().putBoolean("folder_pattern_page_"+p,false).putBoolean(AutoGrid.key("enabled",p),false).apply();LayeredScene.write(activity,new LayeredScene.Document(),false);store.preferences.edit().putInt("wallpaper_source",3).putBoolean("lock_layout",false).putInt("grid_columns",4).putInt("grid_row_dp",112).putBoolean("shuffle_enabled",false).apply();store.ambient=false;store.mode=0;store.save();call(activity,"applySettings",true);}catch(Exception e){throw new AssertionError(e);}});}
    private LauncherStore.Item card(String type,int page){for(LauncherStore.Item item:store.pages.get(page))if(item.key.equals("card:"+type))return item;return null;}
    private DrawerDragController drag(){return (DrawerDragController)field(activity,"drawerDrags");}
    private long begin(View view){SystemClock.sleep(750);test.waitForIdleSync();Rect bounds=rect(view);float x=bounds.centerX(),y=bounds.top+Ui.dp(activity,18);long start=SystemClock.uptimeMillis();pointer(start,MotionEvent.ACTION_DOWN,x,y);SystemClock.sleep(ViewConfiguration.getLongPressTimeout()+180);pointer(start,MotionEvent.ACTION_MOVE,x+Ui.dp(activity,20),y);await(()->drag().active(),"Holding and moving did not start Android's drag: "+view.getContentDescription()+" on desktop "+store.page);return start;}
    private void finish(long start,float x,float y){pointer(start,MotionEvent.ACTION_MOVE,x,y);SystemClock.sleep(100);pointer(start,MotionEvent.ACTION_UP,x,y);await(()->!drag().active(),"Android drag did not finish");}
    private void drawerAndEdges()throws Exception {
        main(()->call(activity,"showStart"));main(()->((EditText)find(v->"Search installed apps".contentEquals(Objects.toString(v.getContentDescription(),"")))).setText("notes"));click("Cards");await(()->find(v->"Notes card. Hold and drag to a desktop.".contentEquals(Objects.toString(v.getContentDescription(),"")))!=null,"Drawer did not show a draggable Notes card");
        View source=find(v->"Notes card. Hold and drag to a desktop.".contentEquals(Objects.toString(v.getContentDescription(),"")));Rect old=rect(source);long start=begin(source);main(()->{SceneRandomizer randomizer=(SceneRandomizer)field(activity,"sceneRandomizer");store.preferences.edit().putBoolean("shuffle_enabled",true).putInt("shuffle_scenes",1<<9).putInt("wallpaper_source",0).apply();randomizer.sync(System.currentTimeMillis());store.preferences.edit().putLong("shuffle_due",System.currentTimeMillis()-1).apply();int before=store.mode;call(activity,"randomizeIfDue");check(store.mode==before&&store.preferences.getLong("shuffle_due",0)<System.currentTimeMillis(),"Automatic shuffle interrupted an active card drag");store.preferences.edit().putBoolean("shuffle_enabled",false).putInt("wallpaper_source",3).apply();});
        int[] position=new int[2];main(()->desktop.getLocationOnScreen(position));float x=position[0]+desktop.getWidth()*.5f,y=position[1]+Ui.dp(activity,200);move(start,old.centerX()+Ui.dp(activity,20),old.top+Ui.dp(activity,18),x,y);finish(start,x,y);await(()->card("notes",0)!=null,"Dragging a card from the drawer did not place it");LauncherStore.Item note=card("notes",0);String id=note.id;check(field(activity,"overlay")==null,"Drawer stayed open after dragging its card");capture("placement093-drawer-card");
        View placed=find(v->("card:"+id).equals(v.getTag()));Rect from=rect(placed);start=begin(placed);float edge=activity.getWindow().getDecorView().getWidth()-Ui.dp(activity,5);move(start,from.centerX()+Ui.dp(activity,20),from.top+Ui.dp(activity,18),edge,from.top+Ui.dp(activity,18));SystemClock.sleep(820);await(()->store.page==1,"Holding a card at the right edge did not change desktops");finish(start,x,y);check(card("notes",0)==null&&card("notes",1)==note&&id.equals(card("notes",1).id),"Edge transfer copied the card or lost its identity");capture("placement093-edge-transfer");
        main(()->{store.pages.get(1).remove(note);store.pages.get(store.pageCount()-1).add(note);store.page=store.pageCount()-1;store.save();desktop.rebuild();});SystemClock.sleep(400);int count=store.pageCount(),page=store.page,cx=note.cellX,cy=note.cellY;placed=find(v->("card:"+id).equals(v.getTag()));from=rect(placed);start=begin(placed);move(start,from.centerX()+Ui.dp(activity,20),from.top+Ui.dp(activity,18),edge,from.top+Ui.dp(activity,18));SystemClock.sleep(820);await(()->store.pageCount()==count+1,"Edge drag did not create a new desktop");main(()->drag().cancel());pointer(start,MotionEvent.ACTION_UP,edge,from.top+Ui.dp(activity,18));await(()->!drag().active()&&store.pageCount()==count&&store.page==page,"Cancel left an empty desktop or changed the active page");check(card("notes",page)==note&&note.cellX==cx&&note.cellY==cy&&store.homePage()==0,"Cancel changed the original card or Home page");
    }
    private void appTiles()throws Exception {
        LauncherStore.Item app=new LauncherStore.Item("builtin:calculator","Resizable calculator");main(()->{store.pages.get(store.page).clear();app.cellX=0;app.cellY=0;store.pages.get(store.page).add(app);store.save();desktop.rebuild();});SystemClock.sleep(400);main(()->call(activity,"menu",app));click("Resize");await(()->app.appTile()&&((WorkspaceFrame)field(desktop,"workspace")).resizing(),"App menu did not enter tile resizing");
        WorkspaceFrame workspace=(WorkspaceFrame)field(desktop,"workspace");RectF selection=(RectF)field(workspace,"selection");int[] p=new int[2];main(()->workspace.getLocationOnScreen(p));float x=p[0]+selection.right-3,y=p[1]+selection.bottom-3;long start=SystemClock.uptimeMillis();pointer(start,MotionEvent.ACTION_DOWN,x,y);move(start,x,y,x+(Integer)field(desktop,"cw"),y+(Integer)field(desktop,"ch"));pointer(start,MotionEvent.ACTION_UP,x+(Integer)field(desktop,"cw"),y+(Integer)field(desktop,"ch"));await(()->app.appWidth==2&&app.appHeight==2,"App edge resize did not persist its full rectangle");
        main(()->{model.set("icon_shape",3);});await(()->find(v->("app-tile:"+app.id).equals(v.getTag()))!=null,"None shape removed the resized app");main(()->{HoldDragFrame surface=(HoldDragFrame)find(v->("app-tile:"+app.id).equals(v.getTag()));IconTile icon=(IconTile)surface.getChildAt(0);View plinth=icon.getChildAt(0);check(plinth.getBackground() instanceof ColorDrawable&&((ColorDrawable)plinth.getBackground()).getColor()==0&&plinth.getElevation()==0,"None left an app shell or shadow behind");check(Ui.iconSurface(activity,true) instanceof IconShellDrawable,"None also removed folder shells");});capture("placement093-unframed-app-tile");
        View surface=find(v->("app-tile:"+app.id).equals(v.getTag()));Rect bounds=rect(surface);start=SystemClock.uptimeMillis();pointer(start,MotionEvent.ACTION_DOWN,bounds.centerX(),bounds.centerY());pointer(start,MotionEvent.ACTION_UP,bounds.centerX(),bounds.centerY());await(()->button("=")!=null,"Tapping a resized app did not launch it");main(()->call(activity,"closePanel"));
        main(()->{try{DesktopBackup.Prepared backup=new DesktopBackup.Prepared(DesktopBackup.capture(activity,model),model);LauncherStore.Item saved=backup.pages.get(store.page).get(0);check(saved.id.equals(app.id)&&saved.appTile()&&saved.appWidth==2&&saved.appHeight==2,"Backup lost resizable app geometry");JSONObject invalid=DesktopBackup.capture(activity,model);invalid.getJSONArray("pages").getJSONObject(store.page).getJSONArray("items").getJSONObject(0).put("appWidth",0);boolean rejected=false;try{new DesktopBackup.Prepared(invalid,model);}catch(Exception expected){rejected=true;}check(rejected,"Invalid app span was accepted");JSONObject exported=model.exportSettings();check(exported.getJSONObject("values").getInt("icon_shape")==3,"None was lost in settings export");}catch(Exception e){throw new AssertionError(e);}call(activity,"menu",app);});click("Use normal shortcut");await(()->!app.appTile()&&find(v->("shortcut:"+app.id).equals(v.getTag()))!=null,"Normal shortcut mode could not be restored");
    }
    private void fill(int page){List<LauncherStore.Item> items=store.pages.get(page);items.clear();int columns=(Integer)field(desktop,"columns"),rows=(Integer)field(desktop,"visibleRows");for(int y=0;y<rows;y++)for(int x=0;x<columns;x++){if((x==0||x==columns-1)&&(y==0||y==rows-1))continue;LauncherStore.Item item=new LauncherStore.Item("builtin:calculator","Filled "+x+","+y);item.cellX=x;item.cellY=y;items.add(item);}}
    private String pageJson(int page){try{JSONArray data=new JSONArray();for(LauncherStore.Item item:store.pages.get(page))data.put(item.json());return data.toString();}catch(Exception e){throw new AssertionError(e);}}
    private void overflow()throws Exception {
        int source=store.page;main(()->{fill(source);store.save();desktop.rebuild();});SystemClock.sleep(300);String original=pageJson(source);int count=store.pageCount();main(()->call(activity,"showPlaceCards"));click("Photos");await(()->store.pageCount()==count+1&&store.page==count&&card("photos",store.page)!=null,"A fragmented screen did not overflow to a new desktop");check(original.equals(pageJson(source)),"Overflow moved existing shortcuts");capture("placement093-overflow-desktop");
        main(()->{while(store.pageCount()<LauncherStore.MAX_PAGES)store.appendPage();for(int p=0;p<store.pageCount();p++)fill(p);store.page=source;store.save();desktop.rebuild();});String before=pageJson(source);main(()->check(desktop.addCard("calendar")==null,"An over-capacity card was added"));check(store.pageCount()==LauncherStore.MAX_PAGES&&before.equals(pageJson(source)),"Failed overflow damaged the filled desktop");
    }
}
